import { get_department_details } from "@/mixins/GetDepartments.js";
export default {
  props: {
    groupVisbility: Boolean,
    rowInfo: Object
  },
  mixins: [get_department_details],
  data() {
    return {
      headers: [{
        text: "Groups",
        value: "department_name",
        sortable: false
      }],
      items: [],
      selectedItems: [],
      singleSelect: false,
      groupVisbile: true,
      groupNotVisibilt: false,
      loading: false
    };
  },
  watch: {
    groupVisbility: {
      async handler() {
        if (this.groupVisbility == true) {
          this.loading = true;
          this.items = [];
          await this.get_department_details();
          this.fecth_details();
        }
      },
      immediate: true
    }
  },
  methods: {
    close_dialog() {
      this.$emit("clicked", 0);
    },
    fecth_details() {
      this.loading = false;
      this.items = this.departmentList;
    }
  }
};
